/**
 * @summary List articles in team collection
 */
export const ListTeamArticlesParams = zod.object({
  id: zod.coerce.string().uuid(),
});

export const ListTeamArticlesQueryParams = zod.object({
  userId: zod.coerce
    .string()
    .uuid()
    .optional()
    .describe(
      "When provided, each item includes the requesting user's per-article read state (isRead\/completedAt) so callers can decide reading mode (basic vs re_read) without an extra request.",
    ),
});

export const ListTeamArticlesResponseItem = zod.object({
  id: zod.string().uuid(),
  teamCollectionId: zod.string().uuid(),
  articleId: zod.string().uuid(),
  addedBy: zod.string().uuid(),
  addedAt: zod.date(),
  article: zod
    .object({
      id: zod.string().uuid(),
      authorId: zod.string().uuid(),
      authorNickname: zod
        .string()
        .nullish()
        .describe(
          "Author's nickname. Populated by listArticles when joining users; may be null on other endpoints.",
        ),
      collectionName: zod
        .string()
        .nullish()
        .describe(
          "Name of the collection this article belongs to (team collection preferred, personal collection fallback). Populated by getArticle; may be null on other endpoints.",
        ),
      collectionId: zod
        .string()
        .uuid()
        .nullish()
        .describe(
          "ID of the team collection this article was delivered through, used for navigation to the collection detail. Null for personal-only or 1:1 articles. Populated by getArticle; may be null on other endpoints.",
        ),
      title: zod.string(),
      content: zod.string(),
      status: zod.enum(["DRAFT", "DIVIDING", "CLOSING", "LETTER"]),
      pages: zod.array(zod.string()).nullish(),
      layoutWidth: zod
        .number()
        .nullish()
        .describe(
          "Container width used when splitting pages (px). Used to ensure consistent line-break rendering across preview and reader screens.",
        ),
      style: zod.object({}).passthrough().nullish(),
      cover: zod
        .object({
          type: zod.enum(["image", "color", "default"]),
          imageUrl: zod
            .string()
            .url()
            .optional()
            .describe("Cover image URL (used when type=image)"),
          bgColor: zod
            .string()
            .optional()
            .describe("Background color hex (used when type=color)"),
          textColor: zod.string().describe("Text color hex for title overlay"),
          align: zod.enum(["left", "center"]),
        })
        .nullish()
        .describe("Article cover display settings. null means default cover."),
      letterAt: zod.date().nullish(),
      sourceArticleId: zod.string().uuid().nullish(),
      isNotice: zod
        .boolean()
        .optional()
        .describe(
          'True when this article was sent as the day\'s \"오늘의 인사\" notice.',
        ),
      noticeDate: zod
        .date()
        .nullish()
        .describe(
          "KST date this article was designated as a notice (YYYY-MM-DD). Null when isNotice=false.",
        ),
      createdAt: zod.date(),
      updatedAt: zod.date(),
    })
    .optional(),
  isRead: zod
    .boolean()
    .optional()
    .describe(
      "Whether the requesting user has ever completed this article. Only present when the listTeamArticles request includes userId.",
    ),
  completedAt: zod
    .date()
    .nullish()
    .describe(
      "Timestamp at which the requesting user first completed this article, or null if never. Only present when the listTeamArticles request includes userId.",
    ),
  sourceArticleId: zod
    .string()
    .uuid()
    .nullish()
    .describe(
      "Shortcut to article.sourceArticleId for threading. Null when the article has no source.",
    ),
  parentInThisCollection: zod
    .boolean()
    .optional()
    .describe(
      "True when the sourceArticleId belongs to another article already in this collection (used for reply threading).",
    ),
  isDeletedPlaceholder: zod
    .boolean()
    .optional()
    .describe(
      "True when the underlying article has been soft-deleted. The row remains so reply threads stay intact.",
    ),
  visibleAt: zod
    .date()
    .nullish()
    .describe(
      "The inbox visibleAt of the requesting user for this article. Null when no requester userId is provided or when there is no inbox row.",
    ),
});
export const ListTeamArticlesResponse = zod.array(ListTeamArticlesResponseItem);

/**
 * Adds an article to the team collection and fans it out to all OWNER/MEMBER inboxes
(excluding the sender). When `asNotice=true`, the sender must be an OWNER and no
other notice may already exist for the current KST notice date for this collection.

 * @summary Add article to team collection (own articles only)
 */
export const AddTeamArticleParams = zod.object({
  id: zod.coerce.string().uuid(),
});

export const AddTeamArticleBody = zod.object({
  articleId: zod.string().uuid(),
  addedBy: zod.string().uuid(),
  asNotice: zod
    .boolean()
    .optional()
    .describe(
      'When true, the addedBy user is the OWNER and this article is designated as today\'s \"오늘의 인사\" for this collection. The server validates ownership and one-per-day uniqueness.',
    ),
});

/**
 * Returns whether the requesting user is an OWNER of the collection and whether a notice
has already been sent for the current KST notice date window. Used by the send screen
to decide if the "오늘의 인사" modal should be shown.

 * @summary Today's "오늘의 인사" status for a (collection, user) pair
 */
export const GetTodayGreetingStatusParams = zod.object({
  id: zod.coerce.string().uuid(),
});

export const GetTodayGreetingStatusQueryParams = zod.object({
  userId: zod.coerce.string().uuid(),
});

export const GetTodayGreetingStatusResponse = zod.object({
  isOwner: zod
    .boolean()
    .describe(
      "Whether the requesting user is an OWNER of this team collection.",
    ),
  alreadySentToday: zod
    .boolean()
    .describe(
      'Whether an \"오늘의 인사\" has already been sent for this collection on the current notice date window.',
    ),
  noticeDate: zod
    .date()
    .describe(
      "The KST notice date (YYYY-MM-DD) the next greeting would be assigned to. Today before 06:00 KST, tomorrow after.",
    ),
});

